mapper.select:
SELECT COALESCE(SUM(CASE WHEN a.ryxxk = '1' AND a.qybjxx = '1' AND a.ryjjsj = '1' AND a.rybjsj = '1' AND a.qybjsj = '1' THEN 1 ELSE 0 END), 0) AS fullAccess,
COALESCE(SUM(CASE WHEN NOT (a.ryxxk = '1' AND a.qybjxx = '1' AND a.ryjjsj = '1' AND a.rybjsj = '1' AND a.qybjsj = '1') AND (COALESCE(a.ryxxk, '0') = '1' OR COALESCE(a.qybjxx, '0') = '1' OR COALESCE(a.ryjjsj, '0') = '1' OR COALESCE(a.rybjsj, '0') = '1' OR COALESCE(a.qybjsj, '0') = '1') THEN 1 ELSE 0 END), 0) AS partialAccess,
COALESCE(SUM(CASE WHEN COALESCE(a.ryxxk, '0') = '0' AND COALESCE(a.qybjxx, '0') = '0' AND COALESCE(a.ryjjsj, '0') = '0' AND COALESCE(a.rybjsj, '0') = '0' AND COALESCE(a.qybjsj, '0') = '0' THEN 1 ELSE 0 END), 0) AS noAccess FROM zlkj_danger_data_accept.accept_company c LEFT JOIN zlkj_danger_data_accept.all_access_status a ON c.code = a.company_code WHERE (c.deleted IS NULL OR c.deleted = 0)
AND c.countycode = #{countycode}
AND c.yq_type = #{yqType}
AND c.parkcode = #{parkCode}
AND c.code IN
#{code}
AND c.is_scqy = #{isScqy}

SELECT CASE e.person_type WHEN '01' THEN '内部人员/员工' WHEN '02' THEN '第三方' WHEN '03' THEN '访客' WHEN '04' THEN '物品' WHEN '05' THEN '车辆' ELSE '未知' END AS name, COUNT(*) AS value FROM zlkj_danger_data_accept.accept_employee_info_formal e
LEFT JOIN zlkj_danger_data_accept.accept_company c ON e.company_code = c.code
WHERE e.deleted = 0
AND e.company_code IN
#{code}
AND c.countycode = #{countycode}
AND c.parkcode = #{parkCode}
AND c.is_scqy = #{isScqy}
GROUP BY e.person_type

