SELECT CASE r.alarm_type WHEN '0' THEN 'SOS报警' WHEN '1' THEN '越界报警' WHEN '2' THEN '滞留报警' WHEN '3' THEN '静止报警' WHEN '4' THEN '离场报警' ELSE '其他' END as name, COUNT(*) as value FROM zlkj_danger_data_accept.rybjsj r
LEFT JOIN zlkj_danger_data_accept.accept_company c ON r.company_code = c.code
r.deleted = '0'
AND r.alarm_time IS NOT NULL AND r.alarm_time != '' AND (r.dispel_time IS NULL OR r.dispel_time = '')
AND r.dispel_time IS NOT NULL AND r.dispel_time != ''
AND c.countycode = #{countycode}
AND c.yq_type = #{yqType}
AND c.yqcode = #{parkCode}
AND r.company_code IN
#{code}
AND c.is_scqy = #{isScqy}
GROUP BY r.alarm_type

SELECT CASE q.alarm_type WHEN '1' THEN '超员报警' WHEN '2' THEN '缺员报警' WHEN '3' THEN '缺岗报警' ELSE '其他' END as name, COUNT(*) as value FROM zlkj_danger_data_accept.qybjsj q
LEFT JOIN zlkj_danger_data_accept.accept_company c ON q.company_code = c.code
q.deleted = '0'
AND q.alarm_time IS NOT NULL AND q.alarm_time != '' AND (q.dispel_time IS NULL OR q.dispel_time = '')
AND q.dispel_time IS NOT NULL AND q.dispel_time != ''
AND c.countycode = #{countycode}
AND c.yq_type = #{yqType}
AND c.yqcode = #{parkCode}
AND q.company_code IN
#{code}
AND c.is_scqy = #{isScqy}
GROUP BY q.alarm_type

SELECT COUNT(*)
FROM zlkj_danger_data_accept.accept_employee_info_formal e

    LEFT JOIN zlkj_danger_data_accept.accept_company c ON e.company_code = c.code


    e.deleted = 0

        AND c.countycode = #{countycode}


        AND c.yq_type = #{yqType}


        AND c.yqcode = #{parkCode}


        AND e.company_code IN

            #{code}



        AND c.is_scqy = #{isScqy}

SELECT CASE r.alarm_type WHEN '0' THEN 'SOS报警' WHEN '1' THEN '越界报警' WHEN '2' THEN '滞留报警' WHEN '3' THEN '静止报警' WHEN '4' THEN '离场报警' ELSE CONCAT('人员其他-', r.alarm_type) END AS name, COUNT(*) AS value FROM zlkj_danger_data_accept.rybjsj r
LEFT JOIN zlkj_danger_data_accept.accept_company c ON r.company_code = c.code
WHERE r.deleted = '0'
AND r.alarm_time IS NOT NULL AND r.alarm_time != '' AND (r.dispel_time IS NULL OR r.dispel_time = '')
AND r.dispel_time IS NOT NULL AND r.dispel_time != ''
AND r.company_code IN
#{code}
AND c.countycode = #{countycode}
AND c.yq_type = #{yqType}
AND c.parkcode = #{parkCode}
AND c.is_scqy = #{isScqy}
GROUP BY r.alarm_type
UNION ALL
SELECT CASE q.alarm_type WHEN '1' THEN '超员报警' WHEN '2' THEN '缺员报警' WHEN '3' THEN '缺岗报警' ELSE CONCAT('区域其他-', q.alarm_type) END AS name, COUNT(*) AS value FROM zlkj_danger_data_accept.qybjsj q
