WHERE q.deleted = '0'
AND q.alarm_time IS NOT NULL AND q.alarm_time != '' AND (q.dispel_time IS NULL OR q.dispel_time = '')
AND q.dispel_time IS NOT NULL AND q.dispel_time != ''
AND q.company_code IN
#{code}
AND c.countycode = #{countycode}
AND c.yq_type = #{yqType}
AND c.parkcode = #{parkCode}
AND c.is_scqy = #{isScqy}
GROUP BY q.alarm_type
UNION ALL
